export default function ({ tickets, pagination, previous }) {
  if (!Array.isArray(tickets) || !pagination || typeof pagination.hasMore !== "boolean")
    throw Error("Invalid Zendesk page");
  const rows = [...(previous?.rows ?? []), ...tickets];
  if (rows.length > 10000) throw Error("Too many tickets");
  const cursor = pagination.afterCursor;
  if (pagination.hasMore && (!cursor || cursor === previous?.cursor))
    throw Error("Missing or repeated Zendesk cursor");
  return { state: { rows, cursor }, more: pagination.hasMore, cursor: cursor ?? null };
}

