export default function ({ items, previous }) {
  const index = (previous?.index ?? -1) + 1,
    t = items[index];
  if (!t) return { state: { index }, more: false, id: 1, subject: "", description: "" };
  if (!Number.isSafeInteger(t.id) || t.id < 1) throw Error("Invalid ticket");
  return {
    state: { index },
    more: true,
    id: t.id,
    subject: t.subject ?? "",
    description: t.description ?? "",
  };
}

