export default async function ({ id }, ctx) {
  const key = "mitre-ticket:" + id,
    s = await ctx.state.get(key);
  if (s?.status === "pending") throw Error("Inspect Zendesk before retrying unknown update");
  if (s?.status === "done") return { key, skip: true };
  await ctx.state.set(key, { status: "pending" });
  return { key, skip: false };
}

