export default function ({ analysis, techniqueField, tacticField }) {
  const t = analysis?.ttp_identification?.mitre_attack_ttps?.[0],
    summary = analysis?.ttp_identification?.alert_summary;
  if (
    typeof summary !== "string" ||
    !summary.trim() ||
    !t ||
    typeof t.technique_id !== "string" ||
    !/^T\d{4}(?:\.\d{3})?$/.test(t.technique_id) ||
    typeof t.tactic !== "string" ||
    !t.tactic.trim()
  )
    throw Error("Missing grounded ATT&CK technique");
  if (
    !Number.isSafeInteger(techniqueField) ||
    techniqueField < 1 ||
    !Number.isSafeInteger(tacticField) ||
    tacticField < 1 ||
    techniqueField === tacticField
  )
    throw Error("Configure custom field IDs");
  return {
    note: "Summary: " + summary,
    fields: [
      { id: techniqueField, value: t.technique_id },
      { id: tacticField, value: t.tactic },
    ],
  };
}

