export default function ({ response }) {
  const vector = response?.data?.[0]?.embedding;
  if (
    !Array.isArray(vector) ||
    vector.length !== 1536 ||
    vector.some((x) => typeof x !== "number" || !Number.isFinite(x))
  )
    throw Error("Invalid 1536-dimensional embedding");
  return { vector };
}

